// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 mintAmount, address target) public {
        vm.assume(target != address(0));
        vm.assume(mintAmount > 0 && mintAmount <= type(uint256).max - c.totalSupply());
        vm.prank(c.owner());
        c.mintToken(target, mintAmount);

        uint256 computedTotalSupply = c.balanceOf(target);
        assertTrue(c.totalSupply() == computedTotalSupply, "totalSupply must equal sum of all balances");
    }
}
